// Lista a situacao de todas as esteiras (usado pelo site E pela Raspberry)
msg.topic = 'SELECT codigo, em_manutencao, parada_em FROM esteiras';
msg.payload = [];
return msg;

// Devolve { esteiras: { esteira1: { parada: false, parada_em: null }, ... } }
var esteiras = {};
(Array.isArray(msg.payload) ? msg.payload : []).forEach(function (linha) {
    esteiras[linha.codigo] = { parada: Boolean(linha.em_manutencao), parada_em: linha.parada_em || null };
});
msg.statusCode = 200;
msg.payload = { esteiras: esteiras };
return msg;

// POST /api/esteiras/esteira1/parada  ->  so PARA a esteira.
// Liberar e com a manutencao (rota /liberar, que exige login e senha).
// Saida 1: segue para o MySQL | Saida 2: erro direto
var codigo = msg.req.params.esteiraId;
var parada = msg.payload && msg.payload.parada;

if (parada === false) {
    msg.statusCode = 403;
    msg.payload = { erro: 'Somente a equipe de manutencao pode liberar a esteira (area Manutencao).' };
    return [null, msg];
}

msg.esteiraId = codigo;
// so marca o horario se ela ainda nao estava parada
msg.topic = 'UPDATE esteiras SET em_manutencao = TRUE, parada_em = IFNULL(parada_em, NOW()) WHERE codigo = ?';
msg.payload = [codigo];
return [msg, null];

var linhas = (msg.payload && msg.payload.affectedRows) || 0;
if (linhas === 0) {
    msg.statusCode = 404;
    msg.payload = { erro: 'Esteira ' + msg.esteiraId + ' nao encontrada' };
    return msg;
}
msg.statusCode = 200;
msg.payload = { esteira: msg.esteiraId, parada: true, status: 'producao parada: aguardando liberacao da manutencao' };
return msg;

// POST /api/esteiras/esteira1/liberar  com  { login, senha, observacao }
// 1o passo: confere se quem esta liberando e da manutencao.
// Saida 1: segue para o MySQL | Saida 2: erro direto
var b = msg.payload || {};
var login = String(b.login || '').trim();
var senha = String(b.senha || '');

if (!login || !senha) {
    msg.statusCode = 401;
    msg.payload = { erro: 'Informe login e senha da manutencao' };
    return [null, msg];
}

function limpar(texto, limite) {
    // o CSV e separado por virgula: tira quebras de linha e troca virgula por ponto e virgula
    return String(texto || '').replace(/[\r\n]+/g, ' ').replace(/,/g, ';').trim().slice(0, limite);
}

msg.esteiraId = msg.req.params.esteiraId;
msg.tipoManutencao = limpar(b.tipo_manutencao, 60);
msg.defeito = limpar(b.defeito, 100);
msg.observacao = limpar(b.observacao, 200);

if (!msg.tipoManutencao) {
    msg.statusCode = 400;
    msg.payload = { erro: 'Selecione o tipo de manutencao' };
    return [null, msg];
}
if (!msg.defeito) {
    msg.statusCode = 400;
    msg.payload = { erro: 'Selecione o defeito encontrado' };
    return [null, msg];
}
msg.topic = "SELECT nome, login FROM usuarios WHERE login = ? AND senha_hash = SHA2(?, 256) AND perfil = 'manutencao'";
msg.payload = [login, senha];
return [msg, null];

// 2o passo: credencial ok? Entao busca a situacao da esteira.
var linhas = Array.isArray(msg.payload) ? msg.payload : [];
if (linhas.length === 0) {
    msg.statusCode = 401;
    msg.payload = { erro: 'Login ou senha invalidos, ou usuario sem perfil de manutencao' };
    return [null, msg];
}
msg.responsavel = {
    nome: String(linhas[0].nome).replace(/[\r\n]+/g, ' ').replace(/,/g, ';'),
    login: linhas[0].login
};
msg.topic = 'SELECT codigo, nome, em_manutencao, parada_em FROM esteiras WHERE codigo = ?';
msg.payload = [msg.esteiraId];
return [msg, null];

// 3o passo: a esteira esta mesmo parada? Calcula quanto tempo ficou parada.
var linhas = Array.isArray(msg.payload) ? msg.payload : [];
if (linhas.length === 0) {
    msg.statusCode = 404;
    msg.payload = { erro: 'Esteira ' + msg.esteiraId + ' nao encontrada' };
    return [null, msg];
}
var esteira = linhas[0];
if (!esteira.em_manutencao) {
    msg.statusCode = 409;
    msg.payload = { erro: 'A ' + esteira.nome + ' nao esta parada' };
    return [null, msg];
}

function dataHoraLocal(d) {
    var dois = function (n) { return String(n).padStart(2, '0'); };
    return d.getFullYear() + '-' + dois(d.getMonth() + 1) + '-' + dois(d.getDate()) +
        'T' + dois(d.getHours()) + ':' + dois(d.getMinutes());
}

var fim = new Date();
var inicio = esteira.parada_em ? new Date(esteira.parada_em) : fim;
if (isNaN(inicio.getTime()) || inicio > fim) inicio = fim;
var minutos = Math.round((fim.getTime() - inicio.getTime()) / 60000);

msg.parada = {
    esteira: esteira.codigo,
    nomeEsteira: esteira.nome,
    inicio: dataHoraLocal(inicio),
    fim: dataHoraLocal(fim),
    minutos: minutos
};
return [msg, null];

// 4o passo: monta a linha do paradas.csv (msg.payload = conteudo atual do arquivo)
var atual = typeof msg.payload === 'string' ? msg.payload : '';
var p = msg.parada;
// tipo e defeito ficam no FINAL da linha: assim as linhas antigas do arquivo continuam validas
var linha = [p.esteira, p.inicio, p.fim, p.minutos, msg.responsavel.nome, msg.responsavel.login,
    msg.observacao, msg.tipoManutencao, msg.defeito].join(',') + '\n';

var texto = '';
if (!atual.trim()) texto += 'esteira,inicio,fim,duracao_min,liberado_por,login,observacao,tipo_manutencao,defeito\n';
else if (!/\n$/.test(atual)) texto += '\n';
msg.payload = texto + linha;
return msg;

// 5o passo: a liberacao tambem conta como manutencao realizada
// (atualiza a "Ultima manutencao" da esteira). msg.payload = conteudo do manutencoes.csv
var atual = typeof msg.payload === 'string' ? msg.payload : '';
var p = msg.parada;

var horas = Math.floor(p.minutos / 60);
var resto = p.minutos % 60;
var tempo = horas > 0 ? horas + 'h ' + resto + 'min' : resto + 'min';
var observacao = 'Liberada apos parada de ' + tempo + (msg.observacao ? ' - ' + msg.observacao : '');

// tipo e defeito no FINAL da linha (as linhas antigas continuam validas)
var linha = [p.fim, p.esteira, msg.responsavel.nome, msg.responsavel.login, observacao,
    msg.tipoManutencao, msg.defeito].join(',') + '\n';
var texto = '';
if (!atual.trim()) texto += 'data_hora,esteira,responsavel,login,observacao,tipo_manutencao,defeito\n';
else if (!/\n$/.test(atual)) texto += '\n';
msg.payload = texto + linha;
return msg;

// 6o passo: tira a parada do cadastro da esteira (a Raspberry volta a gerar leituras)
msg.topic = 'UPDATE esteiras SET em_manutencao = FALSE, parada_em = NULL WHERE codigo = ?';
msg.payload = [msg.esteiraId];
return msg;

msg.statusCode = 200;
msg.payload = {
    status: 'esteira liberada',
    esteira: msg.parada.esteira,
    inicio: msg.parada.inicio,
    fim: msg.parada.fim,
    duracao_min: msg.parada.minutos,
    liberado_por: msg.responsavel.nome,
    tipo_manutencao: msg.tipoManutencao,
    defeito: msg.defeito
};
return msg;

// So trata como "arquivo vazio" quando ele realmente nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o arquivo CSV (aberto no Excel?): ' + texto };
return [null, msg];

// So trata como "arquivo vazio" quando ele realmente nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o arquivo CSV (aberto no Excel?): ' + texto };
return [null, msg];

// msg.payload = conteudo do paradas.csv ('' se ainda nao existe)
// Devolve as paradas mais recentes e o tempo total parado de cada esteira.
var texto = typeof msg.payload === 'string' ? msg.payload : '';
var registros = [];
texto.split(/\r?\n/).forEach(function (linha, i) {
    if (i === 0 || !linha.trim()) return;
    var c = linha.split(',');
    if (c.length < 5) return;
    registros.push({
        esteira: c[0], inicio: c[1], fim: c[2],
        duracao_min: parseInt(c[3], 10) || 0,
        liberado_por: c[4],
        observacao: c[6] || '',
        tipo_manutencao: c[7] || '',
        defeito: c[8] || ''
    });
});

registros.sort(function (a, b) { return a.fim < b.fim ? 1 : (a.fim > b.fim ? -1 : 0); });

var totalPorEsteira = {};
registros.forEach(function (r) {
    totalPorEsteira[r.esteira] = (totalPorEsteira[r.esteira] || 0) + r.duracao_min;
});

msg.statusCode = 200;
msg.payload = { registros: registros.slice(0, 50), total_min_por_esteira: totalPorEsteira };
return msg;

// So trata como "arquivo vazio" quando ele realmente nao existe.
var texto = (msg.error && msg.error.message) ? msg.error.message : '';
if (texto.indexOf('ENOENT') !== -1) {
    msg.payload = '';
    return [msg, null];
}
msg.statusCode = 500;
msg.payload = { erro: 'Nao foi possivel ler o arquivo CSV (aberto no Excel?): ' + texto };
return [null, msg];

var texto = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
msg.statusCode = 500;
msg.payload = { erro: 'Falha na parada/liberacao: ' + texto };
